      double sl = iHigh(NULL,0,iHighest(NULL,0,MODE_HIGH,10,1));
      double tp = Close[0] - (sl-Close[0])*Risk_Reward_Ratio;
      int ticket = OrderSend(Symbol(), OP_SELL, Lots, Bid, slippage, sl, tp, "Sell", 0, 0, clrRed);
